// Tests for changelog.mjs: `node --test plugins/` (the docs site's `test` script).

import assert from "node:assert/strict";
import { test } from "node:test";
import { releaseNotes } from "./changelog.mjs";

test("the releases start at the first release heading, each commit hash a link to the commit", () => {
  const changelog = [
    "# Changelog",
    "",
    "<!-- Generated by a tool. -->",
    "",
    "One version for every package.",
    "",
    "## 1.0.0",
    "",
    "### Minor Changes",
    "",
    "- 2107764: A breaking change.",
    "  - a1b2c3d: An entry nested under it.",
    "- A line that names abcdef0: in its text.",
    "",
  ].join("\n");
  assert.equal(
    releaseNotes(changelog),
    "## 1.0.0\n\n### Minor Changes\n\n" +
      "- [`2107764`](https://github.com/laudebugs/laminapdf/commit/2107764): A breaking change.\n" +
      "  - [`a1b2c3d`](https://github.com/laudebugs/laminapdf/commit/a1b2c3d): An entry nested under it.\n" +
      "- A line that names abcdef0: in its text.\n",
  );
});

test("a changelog without a release is an error", () => {
  assert.throws(() => releaseNotes("# Changelog\n\nNothing yet.\n"), /no release/);
});
